import random
def throw_line():
  r = random.random()
  if r < 0.125: return {'value': 6, 'type': 'yin', 'changing': True}
  if r < 0.5: return {'value': 7, 'type': 'yang', 'changing': False}
  if r < 0.875: return {'value': 8, 'type': 'yin', 'changing': False}
  return {'value': 9, 'type': 'yang', 'changing': True}
def build_hexagram(): return [throw_line() for _ in range(6)]
